import ast

SOURCE = 'def percent(done, total):\n    return done / total * 100\n'
ast.parse(SOURCE)

def percent(done, total):
    if total <= 0:
        raise ValueError('total must be positive')
    return done / total * 100

assert percent(1, 4) == 25
try:
    percent(0, 0)
except ValueError as error:
    assert str(error) == 'total must be positive'
else:
    raise AssertionError('Expected ValueError')
print('syntax and edge-case behavior checked')
